shader.vertex:
            attribute vec3 Position;
            attribute vec4 Color;
            attribute vec2 TexCoord;
            attribute vec4 RenderData;
            attribute float Scale;

            attribute float Time;
			attribute float Enabled;

            varying vec4 Color0;
            varying vec2 TexCoord0;
            varying vec4 RenderDataOut;
            varying float ScaleOut;

            varying float TimeOut;
			varying float EnabledOut;

            uniform mat4 Transform;
            void main(void)
            {
                RenderDataOut = RenderData;
                ScaleOut = Scale;           // Passing data to fragment shader

                TimeOut = Time;             // Passing data to fragment shader
                EnabledOut = Enabled;       // Passing data to fragment shader

                Color0 = Color;
                TexCoord0 = TexCoord;
                gl_Position = Transform * vec4(Position.xyz, 1.0);
            }

shader.fragment:
            varying lowp vec4 Color0;
            varying mediump vec2 TexCoord0;
            varying lowp vec4 RenderDataOut;
            varying lowp float ScaleOut;

            varying lowp float TimeOut;
			varying lowp float EnabledOut;

            uniform sampler2D Texture0;
            void main(void)
            {
				vec2 TearCoord = TexCoord0;
				float tearThresh = mod((TimeOut / 1600.0f), 1.0f);
				if (TexCoord0.y < tearThresh && bool(EnabledOut)) {
					TearCoord.x = TearCoord.x - 0.002f;
				}
                vec4 Color = Color0 * texture2D(Texture0, TearCoord);
				float mult = 0.1f;
				float offset = (TimeOut / 10.0f);
				float coords_check = mod((TexCoord0.y * 80.0f) + offset, 2.0f);

				if (coords_check < 1.4f) {
					mult = 0.3f;
				}
				if (bool(EnabledOut)) {
					Color.r = Color.r * (mult / 1.5f);
					Color.b = Color.b * mult;
					Color.g = (Color.g + (mult / 3.0f)) * 1.1f;
				}
                gl_FragColor = Color;
            }
